import java.util.*;

class Solution {
  public int calculate(String s) {
    Deque<Integer> stack = new ArrayDeque<>();
    int sum = 0, sign = 1;
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (Character.isDigit(c)) {
        int num = 0;
        while (i < s.length() && Character.isDigit(s.charAt(i))) num = num * 10 + (s.charAt(i++) - '0');
        i--;
        sum += sign * num;
      } else if (c == '+') sign = 1;
      else if (c == '-') sign = -1;
      else if (c == '(') {
        stack.push(sum);
        stack.push(sign);
        sum = 0;
        sign = 1;
      } else if (c == ')') {
        sum = stack.pop() * sum + stack.pop();
      }
    }
    return sum;
  }
}
